"""Package this source project and sibling review artifacts; preserve originals."""
from pathlib import Path
import hashlib
import json
import zipfile

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT.parent
ARCHIVE = OUT / '剧院幕后-手机游戏框架.zip'
LAYOUT = json.loads((ROOT / 'data/theatre-layout.json').read_text())
ACTIVE_BASE = Path(LAYOUT['scene']['baseAssetKey']).name

def allowed(path):
    if any(part in {'node_modules', '__pycache__', '.git'} for part in path.parts):
        return False
    if path.name in {'.DS_Store'}:
        return False
    if path.name.startswith('base-clean-v') and path.suffix == '.png' and path.name != ACTIVE_BASE:
        return False
    return True

files = [(p, 'theatre-game/' + str(p.relative_to(ROOT)))
         for p in sorted(ROOT.rglob('*')) if p.is_file() and allowed(p.relative_to(ROOT))]
for name in ['剧院幕后-交互验证.html', '剧院幕后-区域拼装演示.mp4',
             '剧院幕后-手机预览.png', '剧院幕后-完成预览.png', '剧院幕后-干净底图预览.png']:
    path = OUT / name
    if not path.is_file():
        raise FileNotFoundError(path)
    files.append((path, name))

with zipfile.ZipFile(ARCHIVE, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
    for path, name in files:
        archive.write(path, name)

with zipfile.ZipFile(ARCHIVE) as archive:
    assert archive.testzip() is None
    for path, name in files:
        assert hashlib.sha256(archive.read(name)).digest() == hashlib.sha256(path.read_bytes()).digest(), name

print(json.dumps({'archive': str(ARCHIVE), 'bytes': ARCHIVE.stat().st_size,
                  'entries': len(files), 'CRC': 'passed', 'allPayloadHashes': 'passed',
                  'sha256': hashlib.sha256(ARCHIVE.read_bytes()).hexdigest()}, ensure_ascii=False))

游戏会话请先读 manifest.json 与 使用与组装指南.txt。共175个逻辑件。
完整单体在stickers/，场景显示尺寸读取logical_size_wh，位置读取origin_xy。
按render_parts.z整体重绘已放件；同ID的完整主体和技术覆盖/新版前景始终绑定。
regions定义每区所有必需ID、相机视野、吸附完成条件与下一关。
original.png供原图对照，reconstructed.png是全件贴完的最终成图。
intentional_changes列出睡猫、三位不同样貌及紫衣扁头修复。禁止覆盖回旧源脸或旧动物。
preview.html离线打开即可逐件/分区核查。complete-scene-stickers-skill/为永久方法备份。

花香与珠光 · 分割2号 · 完整透明贴纸素材包

共 175 个逻辑物件。全部提供完整透明PNG；原可见覆盖层是技术绘制部分，不是额外游戏贴纸。原图与最终组装图同为 1672×941。

先读 manifest.json。original.png 是本次原图，base.png 是清除可操作物的墙/地板底图，reconstructed.png 是所有元素按本包坐标层叠后的最终图片。stickers/ 保留完整高清单体；runtime/ 为按原图逻辑尺寸生成的轻量完整图；observed/ 为源可见像素技术覆盖图；masks/ 可查原图对应轮廓。

提高清晰度后 PNG 的像素大小不等于场景大小。游戏应使用 origin_xy 和 logical_size_wh 放置；切勿把一千多像素的小壶当作一千多像素场景物件。z 值从小到大。每次贴上或移除后统一按 render_parts.z 重绘，不能按玩家贴的先后来覆盖。

一个物件可能有两个绘制部分：完整主体在正常z，源可见部分在高z，解决手在桌前、身体在桌后的关系。两部分始终绑定同一个ID，只计一个物件和一次拖放。源覆盖图不能当成完整贴纸。用户改绘的人物禁用旧源像素，以新版完整图的像素生成 role=generated_foreground 的绑定前景层，让手臂在桌面/机器前、身体在后，避免旧脸复原。自由移动游戏需动态遮挡；本包默认对应原图的吸附拼图。

主动变化：R004 为蜷窝睡觉的棕白猫；紫衣、白衣、蓝衣女子按用户修正改为不同脸型、五官和适度身形，紫衣女子另修复扁头，头顶和后脑更圆润自然。修改对象的原mask只用于清除旧物，旧原像素覆盖已关闭，最终使用新图。其余已认可小件保持细墨线透明水彩画风。后药柜密集瓶阵与闭合玻璃柜的内置陈列保留为自然柜件；可辨认的顶面独立件另贴。

关卡顺序：大块建筑结构 → 花艺工作区 → 调香工作区 → 蒸馏工作区 → 珠宝匠工作区 → 沙发与地毯区 → 缝纫与衣饰区 → 前景首饰展示区。读取 regions 中的 required_asset_ids；本区全部逻辑件吸附完成再缩放进入 next_region。完成条件包含本区所有大小件，不能只贴完大件就过关。吸附示例：位置误差不超过5原图像素，缩放误差不超过1%。render_parts.hit_mask 是实际alpha的每像素一位base64轮廓，可供离线点击命中；透明角不能当成物件。

previews/ 可查看全部完整贴纸、各区单体和原图对照；guides/ 为分区对应位置编号图。preview.html 可直接离线打开审查：全部贴完、清空、逐件贴、区域放大和完整单体查看。

reconstruct.py 可在安装 Pillow 的Python环境运行，按manifest生成图片。quality/ 保存实际对比；补全与睡猫允许部分变化，因此不宣称逐像素完全相同。已有可见源像素覆盖中，改变数量为 0；全图改变比例为 26.02%（包含完整结构边缘和新睡猫）。

complete-scene-stickers-skill/ 是用户要求永久保存的可复用技能备份。已经安装到本机 Codex skills；以 $complete-scene-stickers 调用。分割规则.txt 和 provenance/ 可供其他游戏会话理解素材来源与补全方法。

