import { GameLayout, RenderPart, StickerPlacement, renderEntryKey } from './GameSession';

const samePoint = (a: { x: number; y: number }, b: { x: number; y: number }): boolean =>
  a.x === b.x && a.y === b.y;

/** Source masks are tied to the original assembly pose and painter queue.
 * Once an object moves, changes scale/rotation/anchor or layer, draw one complete
 * canonical object. The immutable source controls this choice; imported flags
 * cannot re-enable a source-visible overlay on a changed object.
 */
export function assemblyRenderParts(layout: GameLayout, sourceLayout: GameLayout): Map<string, RenderPart[]> {
  const originals = new Map(sourceLayout.stickers.map(owner => [owner.stickerId, owner]));
  const ranks = (value: GameLayout) => new Map([...(value.renderOrder ?? [])]
    .sort((a, b) => a.placementOrder - b.placementOrder)
    .map((entry, index) => [renderEntryKey(entry), index]));
  const currentRanks = ranks(layout), sourceRanks = ranks(sourceLayout);
  const result = new Map<string, RenderPart[]>();
  for (const owner of layout.stickers) {
    const original = originals.get(owner.stickerId);
    const sourceParts = new Map((original?.renderParts ?? []).map(part => [part.partId, part]));
    const atSource = !!original && samePoint(owner.position, original.position)
      && samePoint(owner.anchor, original.anchor) && owner.scale === original.scale
      && owner.rotation === original.rotation && owner.layerIndex === original.layerIndex
      && (owner.renderParts ?? []).length === sourceParts.size
      && (owner.renderParts ?? []).every(part => {
        const source = sourceParts.get(part.partId);
        return !!source && source.layerIndex === part.layerIndex
          && currentRanks.get(`stickerPart:${part.partId}`) === sourceRanks.get(`stickerPart:${part.partId}`);
      });
    if (atSource) { result.set(owner.stickerId, [...(owner.renderParts ?? [])]); continue; }
    // Keep an existing queue identity, so changing a pose never invents a layer.
    const fallback = (owner.renderParts ?? []).find(part => {
      const source = sourceParts.get(part.partId);
      return source?.fullAssetKey && !source.assemblyOnly;
    }) ?? (owner.renderParts ?? []).find(part => !sourceParts.get(part.partId)?.assemblyOnly)
      ?? owner.renderParts?.[0];
    result.set(owner.stickerId, fallback && original ? [{ ...fallback,
      assetKey: original.assetKey, file: original.assetKey,
      sourceSize: { ...owner.sourceSize }, offset: { x: 0, y: 0 },
      requiresAssetIds: [], assemblyOnly: false,
    }] : []);
  }
  return result;
}

export function stickerAssemblyRenderParts(layout: GameLayout, sourceLayout: GameLayout,
  owner: StickerPlacement): RenderPart[] {
  return assemblyRenderParts(layout, sourceLayout).get(owner.stickerId) ?? [];
}

